"use client";

import { useRouter } from "next/navigation";
import { useRef, useState, type FormEvent } from "react";

export function NoteForm() {
  const router = useRouter();
  const formRef = useRef<HTMLFormElement>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setPending(true);
    setError(null);
    try {
      const res = await fetch("/api/notes", {
        method: "POST",
        body: new FormData(e.currentTarget),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error ?? "Failed to create note");
      }
      formRef.current?.reset();
      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setPending(false);
    }
  }

  return (
    <form
      ref={formRef}
      onSubmit={handleSubmit}
      className="mt-4 space-y-2 rounded border border-black/10 p-4 dark:border-white/10"
    >
      <div>
        <label className="block text-xs font-medium opacity-70" htmlFor="title">
          Title
        </label>
        <input
          id="title"
          name="title"
          required
          className="mt-1 w-full rounded border border-black/20 px-2 py-1 text-sm dark:border-white/20 dark:bg-black"
        />
      </div>
      <div>
        <label className="block text-xs font-medium opacity-70" htmlFor="body">
          Body
        </label>
        <textarea
          id="body"
          name="body"
          rows={3}
          className="mt-1 w-full rounded border border-black/20 px-2 py-1 text-sm dark:border-white/20 dark:bg-black"
        />
      </div>
      <div>
        <label className="block text-xs font-medium opacity-70" htmlFor="image">
          Image (optional)
        </label>
        <input
          id="image"
          name="image"
          type="file"
          accept="image/png,image/jpeg,image/gif,image/webp"
          className="mt-1 block text-sm"
        />
      </div>
      {error && <p className="text-xs text-red-600">{error}</p>}
      <button
        type="submit"
        disabled={pending}
        className="rounded bg-foreground px-3 py-1.5 text-sm text-background disabled:opacity-50"
      >
        {pending ? "Saving…" : "Add note"}
      </button>
    </form>
  );
}

